{
  "rule": "Heating converts salt into an active base; the color is clear with 0 active base units, green with 1, and purple with 2 or more. Acid neutralizes one salt/base unit only when a heating step occurs, so acid added without later heat does nothing.",
  "commitments": [
    {
      "events": ["add salt", "add acid", "heat"],
      "predict": "clear",
      "why": "If this were green or purple, acid would not cancel salt when both are present before heating; my rule says one salt and one acid heated together leave zero active units."
    },
    {
      "events": ["add salt", "add salt", "add acid", "heat"],
      "predict": "green",
      "why": "If this were clear, one acid would cancel both salts; if purple, acid would be ignored; my rule says one acid cancels only one of the two heated salts."
    },
    {
      "events": ["heat", "add salt", "add salt", "heat"],
      "predict": "purple",
      "why": "If this were clear or green, a later heat would not activate both salts added after an earlier heat; my rule counts two heated salt units."
    },
    {
      "events": ["add salt", "add salt", "heat", "add acid"],
      "predict": "purple",
      "why": "If this were green or clear, acid would neutralize active salt without being heated; my rule says acid needs a heating step to cancel."
    },
    {
      "events": ["heat", "add salt", "heat"],
      "predict": "green",
      "why": "If this were clear, salt added after a first heat would not be activated by a later heat; my rule leaves one active salt unit, hence green."
    }
  ]
}
